using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    int n;

    if (!(cin >> s >> n))
        return 0;

    const int len = static_cast<int>(s.size());
    const int maxChanges = min(n, len);
    const int width = 2 * len + 1;
    const int offset = len;

    vector<vector<vector<char>>> dp(
        2, vector<vector<char>>(width, vector<char>(maxChanges + 1, false)));
    vector<vector<vector<char>>> next = dp;

    dp[1][offset][0] = true;

    for (char original : s) {
        for (auto& direction : next)
            for (auto& position : direction)
                fill(position.begin(), position.end(), false);

        for (int direction = 0; direction < 2; ++direction) {
            for (int position = -len; position <= len; ++position) {
                for (int changes = 0; changes <= maxChanges; ++changes) {
                    if (!dp[direction][position + offset][changes])
                        continue;

                    for (int changed = 0; changed <= 1; ++changed) {
                        const int newChanges = changes + changed;
                        if (newChanges > maxChanges)
                            continue;

                        char command = original;
                        if (changed)
                            command = (command == 'F' ? 'T' : 'F');

                        int newDirection = direction;
                        int newPosition = position;

                        if (command == 'F')
                            newPosition += direction ? 1 : -1;
                        else
                            newDirection ^= 1;

                        if (newPosition >= -len && newPosition <= len)
                            next[newDirection][newPosition + offset][newChanges] = true;
                    }
                }
            }
        }

        dp.swap(next);
    }

    int answer = 0;

    for (int direction = 0; direction < 2; ++direction) {
        for (int position = -len; position <= len; ++position) {
            for (int changes = 0; changes <= maxChanges; ++changes) {
                if (dp[direction][position + offset][changes] &&
                    changes <= n && (n - changes) % 2 == 0) {
                    answer = max(answer, abs(position));
                }
            }
        }
    }

    cout << answer;
    return 0;
}

