    const int len = static_cast<int>(s.size());
    const int maxFlips = min(n, len);
    const int width = 2 * len + 1;
    const int offset = len;

    auto index = [width, maxFlips, offset](int direction, int position, int flips) {
        return (direction * width + position + offset) * (maxFlips + 1) + flips;
    };

    const int stateCount = 2 * width * (maxFlips + 1);
    vector<unsigned char> current(stateCount, 0);
    vector<unsigned char> next(stateCount, 0);

    current[index(1, 0, 0)] = 1;

    for (char original : s) {
        fill(next.begin(), next.end(), 0);

        for (int direction = 0; direction < 2; ++direction) {
            for (int position = -len; position <= len; ++position) {
                for (int flips = 0; flips <= maxFlips; ++flips) {
                    if (!current[index(direction, position, flips)])
                        continue;

                    for (int toggled = 0; toggled <= 1; ++toggled) {
                        if (flips + toggled > maxFlips)
                            continue;

                        char command = original;
                        if (toggled)
                            command = (command == 'F' ? 'T' : 'F');

                        int newDirection = direction;
                        int newPosition = position;

                        if (command == 'F')
                            newPosition += direction ? 1 : -1;
                        else
                            newDirection ^= 1;

                        next[index(newDirection, newPosition, flips + toggled)] = 1;
                    }
                }
            }
        }

        current.swap(next);
    }

    int answer = 0;

    for (int direction = 0; direction < 2; ++direction) {
        for (int position = -len; position <= len; ++position) {
            for (int flips = 0; flips <= maxFlips; ++flips) {
                if (current[index(direction, position, flips)] &&
                    flips <= n && (n - flips) % 2 == 0) {
                    answer = max(answer, abs(position));
                }
            }
        }
    }

    cout << answer;
    return 0;
}

