using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    long long n;

    if (!(cin >> s >> n))
        return 0;

    const int length = static_cast<int>(s.size());
    const int limit = static_cast<int>(min<long long>(n, length));
    const int width = 2 * length + 1;
    const int offset = length;

    vector<vector<vector<char>>> dp(
        limit + 1, vector<vector<char>>(2, vector<char>(width, false)));
    vector<vector<vector<char>>> next = dp;

    dp[0][1][offset] = true;

    for (char command : s) {
        for (auto& byDirection : next)
            for (auto& byPosition : byDirection)
                fill(byPosition.begin(), byPosition.end(), false);

        for (int used = 0; used <= limit; ++used) {
            for (int direction = 0; direction < 2; ++direction) {
                for (int position = -length; position <= length; ++position) {
                    if (!dp[used][direction][position + offset])
                        continue;

                    for (int changed = 0; changed <= 1; ++changed) {
                        if (used + changed > limit)
                            continue;

                        char current = command;
                        if (changed)
                            current = (current == 'F' ? 'T' : 'F');

                        int newDirection = direction;
                        int newPosition = position;

                        if (current == 'F')
                            newPosition += direction ? 1 : -1;
                        else
                            newDirection ^= 1;

                        next[used + changed][newDirection]
                            [newPosition + offset] = true;
                    }
                }
            }
        }

        dp.swap(next);
    }

    int answer = 0;

    for (int used = 0; used <= limit; ++used) {
        if (used > n || ((n - used) & 1LL))
            continue;

        for (int direction = 0; direction < 2; ++direction) {
            for (int position = -length; position <= length; ++position) {
                if (dp[used][direction][position + offset])
                    answer = max(answer, abs(position));
            }
        }
    }

    cout << answer;
    return 0;
}

