#include <algorithm>
#include <cstdlib>
#include <functional>
#include <iostream>
#include <string>
#include <vector>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    int n;

    cin >> s >> n;

    const int len = static_cast<int>(s.size());
    const int positions = 2 * len + 1;
    vector<int> memo((len + 1) * 2 * positions * (n + 1), -1);

    auto index = [&](int p, int direction, int position, int remaining) {
        return (((p * 2 + direction) * positions + position + len)
                * (n + 1) + remaining);
    };

    function<int(int, int, int, int)> solve =
        [&](int p, int direction, int position, int remaining) -> int {
            if (p == len)
                return remaining == 0 ? abs(position) : 0;

            int& result = memo[index(p, direction, position, remaining)];
            if (result != -1)
                return result;

            result = 0;

            for (int changes = 0; changes <= remaining; ++changes) {
                char command = s[p];

                if (changes % 2 == 1)
                    command = (command == 'F' ? 'T' : 'F');

                if (command == 'F') {
                    result = max(
                        result,
                        solve(p + 1, direction,
                              position + (direction ? 1 : -1),
                              remaining - changes)
                    );
                } else {
                    result = max(
                        result,
                        solve(p + 1, !direction, position,
                              remaining - changes)
                    );
                }
            }

            return result;
        };

    cout << solve(0, 1, 0, n);
    return 0;
}

